"""
    the index of the pattern in lexicographically ordered k-mers
    """
def patternToIndex(pattern: Any) -> object {
    if (len(pattern) == 1) {
        if (pattern == 'A') {
            return 0;
        } elif (pattern == 'C') {
            return 1;
        } elif (pattern == 'G') {
            return 2;
        } elif (pattern == 'T') {
            return 3;
        }
    }
    lastChar = pattern[-1:];
    prefix = pattern[:-1];
    return ((4 * patternToIndex(prefix)) + patternToIndex(lastChar));
}

